local ctx = { Modules = {} }
function ctx:Require(name)
	local value = self.Modules[name]
	if value == nil then
		error("[LumenUI] Unknown or not-yet-initialized module " .. tostring(name), 2)
	end
	return value
end

local order = { "Theme", "Icons", "Lucide", "Helpers", "BulkFade", "Elements", "Notify", "Confirm", "Window" }
for _, name in ipairs(order) do
	local chunk, compileError = loadstring(sources[name], "=LumenUI/" .. name .. ".lua")
	if not chunk then
		error("[LumenUI] " .. name .. " compile failed: " .. tostring(compileError), 0)
	end
	local ok, factory = pcall(chunk)
	if not ok then
		error("[LumenUI] " .. name .. " evaluation failed: " .. tostring(factory), 0)
	end
	ctx.Modules[name] = factory(ctx)
end

return ctx